import { type AudioFrame, AudioResampler } from '@livekit/rtc-node';
import type { TypedEventEmitter as TypedEmitter } from '@livekit/typed-emitter';
import { EventEmitter } from 'node:events';
import type { ReadableStream } from 'node:stream/web';
import { APIConnectionError, APIError } from '../_exceptions.js';
import { calculateAudioDurationSeconds } from '../audio.js';
import type { LanguageCode } from '../language.js';
import { log } from '../log.js';
import type { STTMetrics } from '../metrics/base.js';
import { DeferredReadableStream } from '../stream/deferred_stream.js';
import { type APIConnectOptions, DEFAULT_API_CONNECT_OPTIONS, intervalForRetry } from '../types.js';
import type { AudioBuffer } from '../utils.js';
import { AsyncIterableQueue, delay, startSoon, toError } from '../utils.js';
import type { ConversationItemAddedEvent } from '../voice/events.js';
import type { TimedString } from '../voice/index.js';

/** Indicates start/middle/end of speech */
export enum SpeechEventType {
  /**
   * Indicate the start of speech.
   * If the STT doesn't support this event, this will be emitted at the same time
   * as the first INTERIM_TRANSCRIPT.
   */
  START_OF_SPEECH = 0,
  /**
   * Interim transcript, useful for real-time transcription.
   */
  INTERIM_TRANSCRIPT = 1,
  /**
   * Final transcript, emitted when the STT is confident enough that a certain
   * portion of the speech will not change.
   */
  FINAL_TRANSCRIPT = 2,
  /**
   * Indicate the end of speech, emitted when the user stops speaking.
   * The first alternative is a combination of all the previous FINAL_TRANSCRIPT events.
   */
  END_OF_SPEECH = 3,
  /** Usage event, emitted periodically to indicate usage metrics. */
  RECOGNITION_USAGE = 4,
  /**
   * Preflight transcript, emitted before final transcript when STT has high confidence
   * but hasn't fully committed yet. Includes all pre-committed transcripts including
   * final transcript from the previous STT run.
   */
  PREFLIGHT_TRANSCRIPT = 5,
}

/** SpeechData contains metadata about this {@link SpeechEvent}. */
export interface SpeechData {
  /** Language code of the speech. */
  language: LanguageCode;
  /** Transcribed text. */
  text: string;
  /** Start time of the speech segment in seconds. */
  startTime: number;
  /** End time of the speech segment in seconds. */
  endTime: number;
  /** Confidence score of the transcription (0-1). */
  confidence: number;
  /** Word-level timing information. */
  words?: TimedString[];
  /** Speaker identifier when the provider supports diarization. */
  speakerId?: string | null;
  /**
   * The source languages spoken by the user.
   *
   * Populated by STT services that support translation, where `language` holds the
   * target language and `sourceLanguages` holds the original spoken language(s),
   * or by multi-language detection services where `language` holds the dominant
   * language and `sourceLanguages` holds all detected languages sorted by prevalence.
   *
   * May contain multiple entries when a single utterance spans multiple source languages.
   */
  sourceLanguages?: LanguageCode[];
  /**
   * The original transcription segments in the source language(s), when translation is active.
   * Each entry corresponds to the same-indexed entry in `sourceLanguages`.
   */
  sourceTexts?: string[];
  /**
   * The target language(s) produced by a translation-capable STT service, one entry per
   * consecutive same-language run, parallel to `targetTexts`.
   *
   * `language` holds the dominant or first target language and `targetLanguages` carries the
   * fine-grained per-run breakdown. Populated when translation is active.
   */
  targetLanguages?: LanguageCode[];
  /**
   * The translated transcription segments in the target language(s).
   * Each entry corresponds to the same-indexed entry in `targetLanguages`.
   */
  targetTexts?: string[];
  /**
   * Optional plugin-specific metadata (e.g. voice profile, provider diagnostics).
   *
   * Plugins may populate this with provider-specific data that doesn't map to standard fields.
   */
  metadata?: Record<string, unknown>;
}

export interface RecognitionUsage {
  /** Duration of the audio that was recognized in seconds. */
  audioDuration: number;
  /** Input audio tokens (for token-based STT billing). */
  inputTokens?: number;
  /** Output text tokens (for token-based STT billing). */
  outputTokens?: number;
}

/** SpeechEvent is a packet of speech-to-text data. */
export interface SpeechEvent {
  type: SpeechEventType;
  alternatives?: [SpeechData, ...SpeechData[]];
  requestId?: string;
  recognitionUsage?: RecognitionUsage;
}

/**
 * Describes the capabilities of the STT provider.
 *
 * @remarks
 * At present, the framework only supports providers that have a streaming endpoint.
 */
export interface STTCapabilities {
  streaming: boolean;
  interimResults: boolean;
  /**
   * Whether this STT supports aligned transcripts with word/chunk timestamps.
   * - 'word': Provider returns word-level timestamps
   * - 'chunk': Provider returns chunk-level timestamps (e.g., sentence/phrase boundaries)
   * - false: Provider does not support aligned transcripts
   */
  alignedTranscript?: 'word' | 'chunk' | false;
  /** Whether this STT supports speaker diarization. */
  diarization?: boolean;
  /** Whether the STT supports keyterm prompting */
  keyterms?: boolean;
  /** Whether the STT can natively consume conversation context (see STT._pushConversationItem) */
  chatContext?: boolean;
}

export interface STTError {
  type: 'stt_error';
  timestamp: number;
  label: string;
  error: Error;
  recoverable: boolean;
}

export type STTCallbacks = {
  ['metrics_collected']: (metrics: STTMetrics) => void;
  ['error']: (error: STTError) => void;
};

/**
 * An instance of a speech-to-text adapter.
 *
 * @remarks
 * This class is abstract, and as such cannot be used directly. Instead, use a provider plugin that
 * exports its own child STT class, which inherits this class's methods.
 */
export abstract class STT extends (EventEmitter as new () => TypedEmitter<STTCallbacks>) {
  abstract label: string;
  #capabilities: STTCapabilities;
  #keytermsUnsupportedWarned = false;
  #chatContextUnsupportedWarned = false;

  constructor(capabilities: STTCapabilities) {
    super();
    this.#capabilities = capabilities;
  }

  /** Returns this STT's capabilities */
  get capabilities(): STTCapabilities {
    return this.#capabilities;
  }

  protected updateCapabilities(caps: Partial<STTCapabilities>): void {
    this.#capabilities = { ...this.#capabilities, ...caps };
  }

  /**
   * Get the model name/identifier for this STT instance.
   *
   * @returns The model name if available, "unknown" otherwise.
   *
   * @remarks
   * Plugins should override this property to provide their model information.
   */
  get model(): string {
    return 'unknown';
  }

  /**
   * Get the provider name for this STT instance.
   *
   * @returns The provider name if available, "unknown" otherwise.
   *
   * @remarks
   * Plugins should override this property to provide their provider information.
   */
  get provider(): string {
    return 'unknown';
  }

  /** Receives an audio buffer and returns transcription in the form of a {@link SpeechEvent} */
  async recognize(frame: AudioBuffer, abortSignal?: AbortSignal): Promise<SpeechEvent> {
    const startTime = process.hrtime.bigint();
    const event = await this._recognize(frame, abortSignal);
    const durationMs = Number((process.hrtime.bigint() - startTime) / BigInt(1000000));
    this.emit('metrics_collected', {
      type: 'stt_metrics',
      requestId: event.requestId ?? '',
      timestamp: Date.now(),
      durationMs,
      label: this.label,
      audioDurationMs: Math.round(calculateAudioDurationSeconds(frame) * 1000),
      streamed: false,
      metadata: {
        modelProvider: this.provider,
        modelName: this.model,
      },
    });
    return event;
  }

  protected abstract _recognize(
    frame: AudioBuffer,
    abortSignal?: AbortSignal,
  ): Promise<SpeechEvent>;

  /**
   * Set the framework-managed keyterms (session config + auto-detection).
   *
   * Internal hook called by the framework, kept separate from the user's own keyterms
   * (constructor / `updateOptions`). Plugins that support keyterms override this to
   * store the session set and apply it merged with the user keyterms.
   *
   * @internal
   */
  _updateSessionKeyterms(_keyterms: string[]): void {
    if (!this.#capabilities.keyterms) {
      if (!this.#keytermsUnsupportedWarned) {
        this.#keytermsUnsupportedWarned = true;
        log()
          .child({ stt: this.label })
          .warn('keyterms are not supported by this STT, ignoring keyterms update');
      }
      return;
    }
  }

  /**
   * Feed a new conversation turn to the STT to bias recognition (context carryover).
   *
   * Plugins with native context support set `STTCapabilities.chatContext` and override
   * this to forward the item to their provider's carryover field.
   *
   * @internal
   */
  _pushConversationItem(_ev: ConversationItemAddedEvent): void {
    if (!this.#capabilities.chatContext) {
      if (!this.#chatContextUnsupportedWarned) {
        this.#chatContextUnsupportedWarned = true;
        log()
          .child({ stt: this.label })
          .warn('chat context is not supported by this STT, ignoring chat context update');
      }
      return;
    }
  }

  /**
   * Returns a {@link SpeechStream} that can be used to push audio frames and receive
   * transcriptions
   *
   * @param options - Optional configuration including connection options
   */
  abstract stream(options?: { connOptions?: APIConnectOptions }): SpeechStream;

  async close(): Promise<void> {
    return;
  }
}

/**
 * An instance of a speech-to-text stream, as an asynchronous iterable iterator.
 *
 * @example Looping through frames
 * ```ts
 * for await (const event of stream) {
 *   if (event.type === SpeechEventType.FINAL_TRANSCRIPT) {
 *     console.log(event.alternatives[0].text)
 *   }
 * }
 * ```
 *
 * @remarks
 * This class is abstract, and as such cannot be used directly. Instead, use a provider plugin that
 * exports its own child SpeechStream class, which inherits this class's methods.
 */
export abstract class SpeechStream implements AsyncIterableIterator<SpeechEvent> {
  protected static readonly FLUSH_SENTINEL = Symbol('FLUSH_SENTINEL');
  protected input = new AsyncIterableQueue<AudioFrame | typeof SpeechStream.FLUSH_SENTINEL>();
  protected output = new AsyncIterableQueue<SpeechEvent>();
  protected queue = new AsyncIterableQueue<SpeechEvent>();
  protected neededSampleRate?: number;
  protected resampler?: AudioResampler;
  abstract label: string;
  protected closed = false;
  #stt: STT;
  private deferredInputStream: DeferredReadableStream<AudioFrame>;
  private logger = log();
  private _connOptions: APIConnectOptions;
  private _startTimeOffset: number = 0;
  private _numRetries: number = 0;

  protected abortController = new AbortController();

  constructor(
    stt: STT,
    sampleRate?: number,
    connectionOptions: APIConnectOptions = DEFAULT_API_CONNECT_OPTIONS,
  ) {
    this.#stt = stt;
    this._connOptions = connectionOptions;
    this.deferredInputStream = new DeferredReadableStream<AudioFrame>();
    this.neededSampleRate = sampleRate;
    this.monitorMetrics();
    this.pumpInput();

    // this is a hack to immitate asyncio.create_task so that mainTask
    // is run **after** the constructor has finished. Otherwise we get
    // runtime error when trying to access class variables in the
    // `run` method.
    startSoon(async () => {
      try {
        await this.mainTask();
      } catch {
        // already surfaced via emitError; swallow to avoid unhandled rejection.
      } finally {
        this.queue.close();
      }
    });
  }

  /**
   * Runs the STT with retry logic. Errors are emitted via {@link STT} error events
   * and then re-thrown to end the attempt loop; the caller swallows them.
   *
   * @throws {APIError} When the STT request fails with a non-retryable error
   * @throws {APIConnectionError} When all retry attempts are exhausted
   * @internal Not annotated with Throws<> because this is fire-and-forget via startSoon()
   */
  private async mainTask(): Promise<void> {
    let lastStartTime = Date.now();
    // `_numRetries` is reset by monitorMetrics() on every FINAL_TRANSCRIPT, so the budget
    // applies to consecutive failures rather than to the lifetime of the stream. Providers
    // that recycle their socket on a fixed interval (e.g. Gemini Live's 10-minute session
    // cap) would otherwise exhaust it and permanently stop recognizing on long sessions.
    while (this._numRetries <= this._connOptions.maxRetry) {
      try {
        // Keep provider-relative transcript timestamps linear across reconnect attempts.
        this._startTimeOffset += (Date.now() - lastStartTime) / 1000;
        lastStartTime = Date.now();
        return await this.run();
      } catch (error) {
        // If the stream was intentionally aborted (e.g. session shutdown), exit
        // silently. Downstream listeners may already be detached by this point,
        // and emitting an `error` event here would trigger ERR_UNHANDLED_ERROR
        // in Node's EventEmitter.
        if (this.abortController.signal.aborted) {
          return;
        }

        if (error instanceof APIError) {
          const retryInterval = intervalForRetry(this._connOptions, this._numRetries);

          if (this._connOptions.maxRetry === 0 || !error.retryable) {
            this.emitError({ error, recoverable: false });
            throw error;
          } else if (this._numRetries === this._connOptions.maxRetry) {
            this.emitError({ error, recoverable: false });
            throw new APIConnectionError({
              message: `failed to recognize speech after ${this._connOptions.maxRetry + 1} attempts`,
              options: { retryable: false },
            });
          } else {
            // Don't emit error event for recoverable errors during retry loop
            // to avoid ERR_UNHANDLED_ERROR or premature session termination
            this.logger.warn(
              { stt: this.#stt.label, attempt: this._numRetries + 1, error },
              `failed to recognize speech, retrying in ${retryInterval}ms`,
            );
          }

          if (retryInterval > 0) {
            await delay(retryInterval);
          }

          this._numRetries += 1;
        } else {
          this.emitError({ error: toError(error), recoverable: false });
          throw error;
        }
      }
    }
  }

  private emitError({ error, recoverable }: { error: Error; recoverable: boolean }) {
    this.#stt.emit('error', {
      type: 'stt_error',
      timestamp: Date.now(),
      label: this.#stt.label,
      error,
      recoverable,
    });
  }

  protected async pumpInput() {
    // TODO(AJS-35): Implement STT with webstreams API
    const inputStream = this.deferredInputStream.stream;
    const reader = inputStream.getReader();

    try {
      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        this.pushFrame(value);
      }
    } catch (error) {
      this.logger.error('Error in STTStream mainTask:', error);
    } finally {
      reader.releaseLock();
    }
  }

  protected async monitorMetrics() {
    for await (const event of this.queue) {
      if (!this.output.closed) {
        try {
          this.output.put(event);
        } catch (e) {
          if (e instanceof Error && e.message.includes('Queue is closed')) {
            this.logger.warn(
              { err: e },
              'Queue closed during transcript processing (expected during disconnect)',
            );
          }
        }
      }
      if (event.type === SpeechEventType.FINAL_TRANSCRIPT) {
        // reset the retry count after a successful recognition
        this._numRetries = 0;
      }
      if (event.type !== SpeechEventType.RECOGNITION_USAGE) continue;
      const metrics: STTMetrics = {
        type: 'stt_metrics',
        timestamp: Date.now(),
        requestId: event.requestId!,
        durationMs: 0,
        label: this.#stt.label,
        audioDurationMs: Math.round(event.recognitionUsage!.audioDuration * 1000),
        inputTokens: event.recognitionUsage!.inputTokens ?? 0,
        outputTokens: event.recognitionUsage!.outputTokens ?? 0,
        streamed: true,
        metadata: {
          modelProvider: this.#stt.provider,
          modelName: this.#stt.model,
        },
      };
      this.#stt.emit('metrics_collected', metrics);
    }
    if (!this.output.closed) {
      this.output.close();
    }
  }

  protected abstract run(): Promise<void>;

  protected get abortSignal(): AbortSignal {
    return this.abortController.signal;
  }

  get startTimeOffset(): number {
    return this._startTimeOffset;
  }

  set startTimeOffset(value: number) {
    if (value < 0) {
      throw new Error('startTimeOffset must be non-negative');
    }
    this._startTimeOffset = value;
  }

  updateInputStream(audioStream: ReadableStream<AudioFrame>) {
    this.deferredInputStream.setSource(audioStream);
  }

  detachInputStream() {
    this.deferredInputStream.detachSource();
  }

  /** Push an audio frame to the STT */
  pushFrame(frame: AudioFrame) {
    if (this.input.closed) {
      throw new Error('Input is closed');
    }
    if (this.closed) {
      throw new Error('Stream is closed');
    }

    if (this.neededSampleRate && frame.sampleRate !== this.neededSampleRate) {
      if (!this.resampler) {
        this.resampler = new AudioResampler(frame.sampleRate, this.neededSampleRate);
      }
    }

    if (frame.samplesPerChannel === 0) {
      this.input.put(frame);
      return;
    }

    if (this.resampler) {
      const frames = this.resampler.push(frame);
      for (const frame of frames) {
        this.input.put(frame);
      }
    } else {
      this.input.put(frame);
    }
  }

  /** Flush the STT, causing it to process all pending text */
  flush() {
    if (this.input.closed) {
      throw new Error('Input is closed');
    }
    if (this.closed) {
      throw new Error('Stream is closed');
    }
    this.input.put(SpeechStream.FLUSH_SENTINEL);
  }

  /** Mark the input as ended and forbid additional pushes */
  endInput() {
    if (this.input.closed) {
      throw new Error('Input is closed');
    }
    if (this.closed) {
      throw new Error('Stream is closed');
    }
    this.input.close();
  }

  next(): Promise<IteratorResult<SpeechEvent>> {
    return this.output.next();
  }

  /** Close both the input and output of the STT stream */
  close() {
    if (!this.input.closed) this.input.close();
    if (!this.queue.closed) this.queue.close();
    if (!this.output.closed) this.output.close();
    if (!this.abortController.signal.aborted) this.abortController.abort();
    this.resampler?.close();
    this.closed = true;
  }

  [Symbol.asyncIterator](): SpeechStream {
    return this;
  }
}
